    private String raw(Access a,UUID id){var rows=jdbc.query("SELECT to_jsonb(t)::text FROM orders.organization_action_task t WHERE organization_id=? AND id=?",(r,n)->r.getString(1),org(a),id);if(rows.size()!=1)throw fail("RESOURCE_NOT_FOUND");decode(a,rows.getFirst());return rows.getFirst();}
