    @Override public Change create(Access a,Input input,UUID key){if(input==null||!Set.of("PREPARATION","SHIPMENT").contains(input.targetKind())||input.targetId()==null||!Objects.equals(input.type(),input.targetKind().equals("PREPARATION")?"PREPARATION_REVIEW":"SHIPMENT_FOLLOW_UP"))throw fail("VALIDATION_FAILED");Input in=new Input(input.targetKind(),input.targetId(),input.type(),text(input.title(),160),text(input.details(),2000),priority(input.priority()),input.dueAt());String payload=JSON.writeValueAsString(in);var previous=prior(a,"CREATE",key);if(previous.isPresent())return replay(a,"CREATE",previous.get().task(),0,payload,previous.get());Source target=target(a,in.targetKind(),in.targetId(),true);permit(a,"shipment.actions.manage",target.facility());a.scope().requireActiveFacility(target.facility());Instant due=due(in.dueAt()),now=clock.instant().truncatedTo(ChronoUnit.MICROS);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO orders.organization_action_task VALUES(?,?,?,?,?,?,?,?, 'OPEN',?,NULL,?,?,1,?,?,NULL)",id,org(a),target.facility(),in.targetKind().equals("PREPARATION")?in.targetId():null,in.targetKind().equals("SHIPMENT")?in.targetId():null,in.type(),in.title(),in.details(),in.priority(),due==null?null:Timestamp.from(due),due==null?null:Timestamp.from(due),Timestamp.from(now),Timestamp.from(now));return evidence(a,"CREATE",key,id,0,payload,null);}
